CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_product_active(p_product_id uuid, p_active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_product_id uuid;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'products.toggle_active'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para alterar o status de produtos.';
  end if;

  if p_product_id is null then
    raise exception using
      errcode = '22004',
      message = 'Produto não informado.';
  end if;

  if p_active is null then
    raise exception using
      errcode = '22004',
      message = 'Status não informado.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem tenant ativo.';
  end if;

  update public.products
  set
    active = p_active,
    updated_at = now()
  where id = p_product_id
    and tenant_id = v_tenant_id
  returning id into v_product_id;

  if v_product_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Produto não encontrado nesta empresa.';
  end if;

  return v_product_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_product(p_product_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_product_id uuid;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'products.delete'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para excluir produtos.';
  end if;

  if p_product_id is null then
    raise exception using
      errcode = '22004',
      message = 'Produto não informado.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem tenant ativo.';
  end if;

  /*
   * Bloqueia a linha antes de verificar movimentações.
   */
  select product.id
  into v_product_id
  from public.products as product
  where product.id = p_product_id
    and product.tenant_id = v_tenant_id
  for update;

  if v_product_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'Produto não encontrado nesta empresa.';
  end if;

  /*
   * products possui ON DELETE CASCADE em stock_movements.
   *
   * Sem esta validação, excluir o produto apagaria todo o
   * histórico de entradas e retiradas.
   */
  if exists (
    select 1
    from public.stock_movements as movement
    where movement.product_id = p_product_id
      and movement.tenant_id = v_tenant_id
  ) then
    raise exception using
      errcode = '23503',
      message = 'Produtos com movimentações não podem ser excluídos. Desative o produto para preservar o histórico.';
  end if;

  delete from public.products
  where id = p_product_id
    and tenant_id = v_tenant_id;

  return v_product_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_stock_movement(p_product_id uuid, p_type text, p_quantity integer, p_unit_cost numeric, p_notes text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_tenant_id uuid;

  v_type text;
  v_required_permission text;

  v_old_stock integer;
  v_new_stock integer;
  v_product_active boolean;

  v_unit_cost numeric;
  v_notes text;

  v_movement_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem tenant ativo.';
  end if;

  if p_product_id is null then
    raise exception using
      errcode = '22004',
      message = 'Produto não informado.';
  end if;

  v_type := upper(
    btrim(
      coalesce(p_type, '')
    )
  );

  /*
   * Define a permissão necessária com base no tipo.
   */
  case v_type
    when 'IN' then
      v_required_permission := 'stock.in';

    when 'OUT' then
      v_required_permission := 'stock.out';

    when 'ADJUST' then
      v_required_permission := 'stock.adjust';

    else
      raise exception using
        errcode = '22023',
        message = 'Tipo de movimentação inválido.';
  end case;

  if not private.has_permission(
    v_required_permission
  ) then
    raise exception using
      errcode = '42501',
      message = case v_type
        when 'IN' then
          'Você não possui permissão para registrar entradas.'
        when 'OUT' then
          'Você não possui permissão para registrar retiradas.'
        else
          'Você não possui permissão para ajustar o estoque.'
      end;
  end if;

  /*
   * IN e OUT representam quantidades movimentadas.
   * Portanto, precisam ser maiores que zero.
   *
   * ADJUST representa o novo estoque absoluto e aceita zero.
   */
  if v_type in ('IN', 'OUT') then
    if p_quantity is null or p_quantity <= 0 then
      raise exception using
        errcode = '22023',
        message = 'A quantidade deve ser maior que zero.';
    end if;
  else
    if p_quantity is null or p_quantity < 0 then
      raise exception using
        errcode = '22023',
        message = 'O novo estoque não pode ser negativo.';
    end if;
  end if;

  if p_unit_cost is not null and p_unit_cost < 0 then
    raise exception using
      errcode = '22023',
      message = 'O custo unitário não pode ser negativo.';
  end if;

  /*
   * Custo unitário faz sentido apenas em entradas.
   */
  if v_type = 'IN' then
    if
      p_unit_cost is not null
      and not private.has_permission(
        'products.view_cost'
      )
    then
      raise exception using
        errcode = '42501',
        message = 'Você não possui permissão para informar o custo unitário.';
    end if;

    v_unit_cost := p_unit_cost;
  else
    v_unit_cost := null;
  end if;

  v_notes := nullif(
    btrim(p_notes),
    ''
  );

  /*
   * Busca e bloqueia o produto.
   *
   * FOR UPDATE impede que duas movimentações simultâneas
   * calculem o estoque a partir do mesmo valor antigo.
   */
  select
    product.current_stock,
    product.active
  into
    v_old_stock,
    v_product_active
  from public.products as product
  where product.id = p_product_id
    and product.tenant_id = v_tenant_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Produto não encontrado nesta empresa.';
  end if;

  if v_product_active = false then
    raise exception using
      errcode = '22023',
      message = 'Não é possível movimentar um produto inativo.';
  end if;

  /*
   * Calcula o estoque somente no banco.
   */
  case v_type
    when 'IN' then
      v_new_stock :=
        v_old_stock + p_quantity;

    when 'OUT' then
      v_new_stock :=
        v_old_stock - p_quantity;

    when 'ADJUST' then
      v_new_stock :=
        p_quantity;
  end case;

  if v_new_stock < 0 then
    raise exception using
      errcode = '22023',
      message =
        'Estoque insuficiente. A retirada deixaria o estoque negativo.';
  end if;

  update public.products
  set
    current_stock = v_new_stock,
    updated_at = now()
  where id = p_product_id
    and tenant_id = v_tenant_id;

  insert into public.stock_movements (
    tenant_id,
    product_id,
    type,
    quantity,
    unit_cost,
    notes,
    created_by
  )
  values (
    v_tenant_id,
    p_product_id,
    v_type,
    p_quantity,
    v_unit_cost,
    v_notes,
    v_user_id
  )
  returning id into v_movement_id;

  return jsonb_build_object(
    'movement_id',
    v_movement_id,
    'product_id',
    p_product_id,
    'type',
    v_type,
    'quantity',
    p_quantity,
    'old_stock',
    v_old_stock,
    'new_stock',
    v_new_stock,
    'created_by',
    v_user_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.list_stock_products()
 RETURNS TABLE(id uuid, name text, unit text, current_stock integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not (
    private.has_permission('stock.in')
    or private.has_permission('stock.out')
    or private.has_permission('stock.adjust')
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para movimentar estoque.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem tenant ativo.';
  end if;

  return query
  select
    product.id,
    product.name,
    product.unit,
    product.current_stock

  from public.products as product

  where product.tenant_id = v_tenant_id
    and product.active = true

  order by lower(product.name);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_member_invitation(p_email text, p_token_hash text, p_permission_keys text[], p_expires_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_email text;
  v_permission_keys text[];
  v_invitation_id uuid;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'members.invite'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para convidar usuários.';
  end if;

  v_tenant_id :=
    private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem empresa ativa.';
  end if;

  v_email :=
    lower(nullif(btrim(p_email), ''));

  if v_email is null then
    raise exception using
      errcode = '22023',
      message = 'E-mail obrigatório.';
  end if;

  if v_email !~
    '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  then
    raise exception using
      errcode = '22023',
      message = 'E-mail inválido.';
  end if;

  if p_token_hash is null
    or p_token_hash !~ '^[a-f0-9]{64}$'
  then
    raise exception using
      errcode = '22023',
      message = 'Token de convite inválido.';
  end if;

  if p_expires_at is null
    or p_expires_at <= now()
  then
    raise exception using
      errcode = '22023',
      message = 'A validade do convite é inválida.';
  end if;

  if p_expires_at > now() + interval '30 days'
  then
    raise exception using
      errcode = '22023',
      message = 'O convite não pode durar mais que 30 dias.';
  end if;

  if exists (
    select 1
    from public.users as app_user
    where lower(app_user.email) = v_email
  ) then
    raise exception using
      errcode = '23505',
      message = 'Este e-mail já está vinculado a uma empresa.';
  end if;

  select coalesce(
    array_agg(
      distinct requested.permission_key
      order by requested.permission_key
    ),
    array[]::text[]
  )
  into v_permission_keys
  from unnest(
    coalesce(
      p_permission_keys,
      array[]::text[]
    )
  ) as requested(permission_key);

  if exists (
    select 1
    from unnest(v_permission_keys)
      as requested(permission_key)

    left join public.permissions
      as permission
      on permission.key =
        requested.permission_key
      and permission.assignable_to_member = true

    where permission.key is null
  ) then
    raise exception using
      errcode = '22023',
      message = 'Uma ou mais permissões não podem ser atribuídas.';
  end if;

  update private.member_invitations
  set
    status = 'REVOKED',
    revoked_at = now(),
    updated_at = now()
  where tenant_id = v_tenant_id
    and lower(email) = v_email
    and status = 'PENDING';

  insert into private.member_invitations (
    tenant_id,
    email,
    token_hash,
    permission_keys,
    invited_by,
    expires_at
  )
  values (
    v_tenant_id,
    v_email,
    p_token_hash,
    v_permission_keys,
    auth.uid(),
    p_expires_at
  )
  returning id
  into v_invitation_id;

  return v_invitation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_member_permissions(p_member_id uuid, p_permission_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_member_role text;
  v_permission_keys text[];
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'members.permissions'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para administrar permissões.';
  end if;

  if p_member_id is null then
    raise exception using
      errcode = '22004',
      message = 'Usuário não informado.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem empresa ativa.';
  end if;

  select app_user.role
  into v_member_role
  from public.users as app_user
  where app_user.id = p_member_id
    and app_user.tenant_id = v_tenant_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Usuário não encontrado nesta empresa.';
  end if;

  if v_member_role = 'owner' then
    raise exception using
      errcode = '42501',
      message = 'As permissões do proprietário não podem ser alteradas.';
  end if;

  v_permission_keys :=
    coalesce(
      p_permission_keys,
      array[]::text[]
    );

  if exists (
    select 1
    from unnest(v_permission_keys)
      as requested_permission(key)

    left join public.permissions
      as permission
      on permission.key =
        requested_permission.key
      and permission.assignable_to_member = true

    where permission.key is null
  ) then
    raise exception using
      errcode = '22023',
      message = 'Uma ou mais permissões são inválidas ou não podem ser atribuídas.';
  end if;

  delete from private.user_permissions
  where user_id = p_member_id;

  insert into private.user_permissions (
    user_id,
    permission_key,
    granted_by
  )
  select distinct
    p_member_id,
    requested_permission.key,
    auth.uid()
  from unnest(v_permission_keys)
    as requested_permission(key);

  return jsonb_build_object(
    'member_id',
    p_member_id,

    'permissions',
    to_jsonb(v_permission_keys)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_member_active(p_member_id uuid, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_member_role text;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'members.deactivate'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para ativar ou desativar usuários.';
  end if;

  if p_member_id is null then
    raise exception using
      errcode = '22004',
      message = 'Usuário não informado.';
  end if;

  if p_active is null then
    raise exception using
      errcode = '22004',
      message = 'Status não informado.';
  end if;

  v_tenant_id := private.current_tenant_id();

  if v_tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário sem empresa ativa.';
  end if;

  select app_user.role
  into v_member_role
  from public.users as app_user
  where app_user.id = p_member_id
    and app_user.tenant_id = v_tenant_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Usuário não encontrado nesta empresa.';
  end if;

  if v_member_role = 'owner' then
    raise exception using
      errcode = '42501',
      message = 'O proprietário não pode ser desativado.';
  end if;

  update public.users
  set active = p_active
  where id = p_member_id
    and tenant_id = v_tenant_id;

  return jsonb_build_object(
    'member_id',
    p_member_id,
    'active',
    p_active
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_member_invitation(p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
begin
  if auth.uid() is null then
    raise exception using
      errcode = '42501',
      message = 'Usuário não autenticado.';
  end if;

  if not private.has_permission(
    'members.invite'
  ) then
    raise exception using
      errcode = '42501',
      message = 'Você não possui permissão para revogar convites.';
  end if;

  v_tenant_id :=
    private.current_tenant_id();

  update private.member_invitations
  set
    status = 'REVOKED',
    revoked_at = now(),
    updated_at = now()
  where id = p_invitation_id
    and tenant_id = v_tenant_id
    and status = 'PENDING';

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'Convite pendente não encontrado.';
  end if;

  return jsonb_build_object(
    'id',
    p_invitation_id,

    'status',
    'REVOKED'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_product(p_name text, p_sku text, p_description text, p_image_url text, p_unit text, p_cost_price numeric, p_sale_price numeric, p_min_stock integer, p_current_stock integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tenant_id uuid;
  v_product_id uuid;
BEGIN
  SELECT u.tenant_id INTO v_tenant_id
  FROM public.users u
  WHERE u.id = auth.uid();

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado';
  END IF;

  INSERT INTO public.products (
    tenant_id, name, sku, description, image_url, unit,
    cost_price, sale_price, min_stock, current_stock
  ) VALUES (
    v_tenant_id, p_name, p_sku, p_description, p_image_url, p_unit,
    p_cost_price, p_sale_price, p_min_stock, p_current_stock
  )
  RETURNING id INTO v_product_id;

  RETURN v_product_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_company_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_signup_flow text;
  v_full_name text;

  v_company_name text;
  v_base_slug text;
  v_slug text;
  v_tenant_id uuid;

  v_invitation_hash text;
  v_invitation private.member_invitations%rowtype;
begin
  if new.email is null then
    raise exception using
      errcode = '22023',
      message = 'O usuário precisa possuir um e-mail.';
  end if;

  v_signup_flow :=
    nullif(
      btrim(
        new.raw_user_meta_data
          ->> 'signup_flow'
      ),
      ''
    );

  v_full_name :=
    nullif(
      btrim(
        new.raw_user_meta_data
          ->> 'full_name'
      ),
      ''
    );

  if v_full_name is null
    or char_length(v_full_name) < 2
  then
    raise exception using
      errcode = '22023',
      message = 'Nome do usuário inválido.';
  end if;

  -- ==========================================================
  -- CADASTRO NORMAL: CRIA EMPRESA E PROPRIETÁRIO
  -- ==========================================================

  if v_signup_flow = 'create_company' then
    v_company_name :=
      nullif(
        btrim(
          new.raw_user_meta_data
            ->> 'company_name'
        ),
        ''
      );

    if v_company_name is null
      or char_length(v_company_name) < 2
    then
      raise exception using
        errcode = '22023',
        message = 'Nome da empresa inválido.';
    end if;

    v_base_slug := lower(
      regexp_replace(
        v_company_name,
        '[^a-zA-Z0-9]+',
        '-',
        'g'
      )
    );

    v_base_slug :=
      trim(both '-' from v_base_slug);

    if v_base_slug = '' then
      v_base_slug := 'empresa';
    end if;

    /*
     * O UUID garante que empresas com o mesmo nome
     * recebam identificadores diferentes.
     */
    v_slug :=
      left(v_base_slug, 26)
      || '-'
      || replace(new.id::text, '-', '');

    insert into public.tenants (
      name,
      slug
    )
    values (
      v_company_name,
      v_slug
    )
    returning id
    into v_tenant_id;

    insert into public.users (
      id,
      tenant_id,
      email,
      full_name,
      role,
      active
    )
    values (
      new.id,
      v_tenant_id,
      lower(new.email),
      v_full_name,
      'owner',
      true
    );

    return new;
  end if;


  -- ==========================================================
  -- CADASTRO POR CONVITE: ENTRA EM EMPRESA EXISTENTE
  -- ==========================================================

  if v_signup_flow = 'accept_invitation' then
    v_invitation_hash :=
      nullif(
        btrim(
          new.raw_user_meta_data
            ->> 'invitation_token_hash'
        ),
        ''
      );

    if v_invitation_hash is null
      or v_invitation_hash !~ '^[a-f0-9]{64}$'
    then
      raise exception using
        errcode = '22023',
        message = 'Token de convite inválido.';
    end if;

    select invitation.*
    into v_invitation
    from private.member_invitations
      as invitation
    where invitation.token_hash =
        v_invitation_hash
      and lower(invitation.email) =
        lower(new.email)
      and invitation.status = 'PENDING'
      and invitation.expires_at > now()
    for update;

    if not found then
      raise exception using
        errcode = '42501',
        message = 'Convite inválido, expirado ou já utilizado.';
    end if;

    if exists (
      select 1
      from public.users as app_user
      where lower(app_user.email) =
        lower(new.email)
    ) then
      raise exception using
        errcode = '23505',
        message = 'Este e-mail já pertence a uma empresa.';
    end if;

    insert into public.users (
      id,
      tenant_id,
      email,
      full_name,
      role,
      active
    )
    values (
      new.id,
      v_invitation.tenant_id,
      lower(new.email),
      v_full_name,
      'member',
      true
    );

    insert into private.user_permissions (
      user_id,
      permission_key,
      granted_by
    )
    select distinct
      new.id,
      requested.permission_key,
      v_invitation.invited_by
    from unnest(
      coalesce(
        v_invitation.permission_keys,
        array[]::text[]
      )
    ) as requested(permission_key)
    join public.permissions as permission
      on permission.key =
        requested.permission_key
      and permission.assignable_to_member =
        true
    on conflict (
      user_id,
      permission_key
    ) do nothing;

    update private.member_invitations
    set
      status = 'ACCEPTED',
      accepted_by = new.id,
      accepted_at = now(),
      updated_at = now()
    where id = v_invitation.id;

    return new;
  end if;


  -- ==========================================================
  -- FLUXO DESCONHECIDO
  -- ==========================================================

  raise exception using
    errcode = '22023',
    message = 'Fluxo de cadastro inválido.';
end;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
