$function$

CREATE OR REPLACE FUNCTION public.update_product(p_product_id uuid, p_name text, p_sku text, p_description text, p_image_url text, p_unit text, p_sale_price numeric, p_min_stock integer, p_cost_price numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tenant_id uuid;
BEGIN
  SELECT u.tenant_id INTO v_tenant_id
  FROM public.users u
  WHERE u.id = auth.uid();

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Tenant não encontrado';
  END IF;

  UPDATE public.products p
  SET name = p_name, sku = p_sku, description = p_description,
      image_url = p_image_url, unit = p_unit, sale_price = p_sale_price,
      min_stock = p_min_stock, cost_price = COALESCE(p_cost_price, p.cost_price)
  WHERE p.id = p_product_id AND p.tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto não encontrado';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_company_settings(p_name text, p_slug text)
