 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant_id uuid;
begin
  select tenant_id into v_tenant_id
  from public.users
  where id = auth.uid();

  if v_tenant_id is null then
    raise exception 'Tenant não encontrado';
